args.CommandLine:
$addr = if ($env:ANTIGRAVITY_LS_ADDRESS) { $env:ANTIGRAVITY_LS_ADDRESS } else { "localhost:5387" }
$resp = Invoke-RestMethod -Method Post -Uri "http://$addr/exa.language_server_pb.LanguageServerService/GetAllPlugins" -Headers @{ "Content-Type"="application/json"; "x-codeium-csrf-token"=$env:ANTIGRAVITY_CSRF_TOKEN } -Body '{"workspaceUris":["file:///d:/%E9%A1%B9%E7%9B%AEsession/blender-supercar"]}'
$resp.plugins | ForEach-Object { [PSCustomObject]@{ name=$_.name; dir=($_.path -split '[/\\]')[-1]; disabled=[bool]$_.disabled; isGlobal=$_.isGlobal } } | ConvertTo-Json -Compress
